const CATCHUP_LEAD_HOURS = $('Config (mirrors engagements/aerchain/precall_config.json)').item.json.catchup_threshold_hours;
const triggerMode = $('Config (mirrors engagements/aerchain/precall_config.json)').item.json.trigger_mode;
const internalDomains = new Set($('Config (mirrors engagements/aerchain/precall_config.json)').item.json.internal_domains);
const today = new Date(); today.setUTCHours(0, 0, 0, 0);

function classifyWindow(callStart) {
  const d = new Date(Date.UTC(callStart.getUTCFullYear(), callStart.getUTCMonth(), callStart.getUTCDate()));
  const deltaDays = Math.round((d - today) / 86400000);
  if (deltaDays === 2) return 't2';
  if (deltaDays === 1) return 't1';
  return 'none';
}

function leadTimeHours(bookedAt, callStart) {
  return (callStart - bookedAt) / 3600000;
}

function needsCatchup(bookedAt, callStart) {
  const h = leadTimeHours(bookedAt, callStart);
  return h >= 0 && h < CATCHUP_LEAD_HOURS;
}

function planAction(event) {
  const callStart = new Date(event.start.dateTime);
  const bookedAt = new Date(event.created);
  const flags = event.extendedProperties?.private || {};
  const briefingSent = flags.briefingSent === 'true';
  const summarySent = flags.summarySent === 'true';

  if (summarySent) return 'skip';
  if (triggerMode === 'hybrid' && !briefingSent && needsCatchup(bookedAt, callStart)) {
    return 'send_catchup_briefing';
  }
  const window = classifyWindow(callStart);
  if (window === 't2' && !briefingSent) return 'send_briefing';
  if (window === 't1' && !summarySent) return 'send_recap';
  return 'skip';
}

function prospectAttendee(event) {
  for (const a of (event.attendees || [])) {
    const domain = (a.email || '').split('@')[1] || '';
    if (!internalDomains.has(domain.toLowerCase())) return a;
  }
  return null;
}

return items.map((item) => {
  const event = item.json;
  const prospect = prospectAttendee(event);
  return {
    json: {
      event_id: event.id,
      action: planAction(event),
      prospect_email: prospect ? prospect.email : null,
      event,
    },
  };
});

const triggerMode = $('Config (mirrors engagements/aerchain/precall_config.json)').item.json.trigger_mode;
const CATCHUP_LEAD_HOURS = $('Config (mirrors engagements/aerchain/precall_config.json)').item.json.catchup_threshold_hours;
const event = $json.body;

const callStart = new Date(event.start.dateTime);
const bookedAt = new Date(event.created);
const leadHours = (callStart - bookedAt) / 3600000;
const isCatchup = triggerMode === 'hybrid' && leadHours >= 0 && leadHours < CATCHUP_LEAD_HOURS;

return [{ json: { event_id: event.id, action: isCatchup ? 'send_catchup_briefing' : 'skip', prospect_email: null, event } }];

const company = $json.properties || {};
const needsWebClassification = !company.industry || company.industry.trim() === '';
return [{ json: { ...$json, needs_web_classification: needsWebClassification } }];

